            "type": "ds.search"
        },
        "ds_u7ROugjs_ds_glU4SPhJ_ds_gHIjvHTs_ds_recordtype_summary": {
            "name": "dnsguardai_dashboards_recordtype_hinfo_summary copy 2",
            "options": {
                "query": "| inputlookup anomalous_dns_lookup\n| where anomalous_type==\"HINFO Record Anomalies\"\n| stats count",
                "queryParameters": {
                    "earliest": "$global_time.earliest$",
                    "latest": "$global_time.latest$"
                }
            },
            "type": "ds.search"
        },
        "ds_uQG4fwGl_ds_Ap7NdQ1B": {
            "name": "dnsguardai_dashboards_beaconing_affected_source_ip",
            "options": {
                "query": "| `dns_data` | `extract_sub_domain` | `lookup_anomalous_dns(\\\"Beaconing\\\")` | dedup src \n| stats count"
            },
            "type": "ds.search"
        },
        "ds_wChB0JqS_ds_bkKtQGI3": {
            "name": "dnsguardai_dashboards_beaconing_dns_by_src copy 1",
            "options": {
                "query": "| `dns_data` | fields _time, src, query \n| `extract_sub_domain`\n| `lookup_anomalous_dns(\\\"C2 Tunneling\\\")`\n| stats count by src domain\n| table src domain",
                "queryParameters": {
                    "earliest": "$global_time.earliest$",
                    "latest": "$global_time.latest$"
                }
            },
            "type": "ds.search"
        },
        "ds_wHrBTzr7": {
            "name": "dnsguardai_dashboards_clustering_cluster0_avg_query_length",
            "options": {
                "query": "| summary dns_behavior_clusters\n| where cluster==0\n| table avg_len",
                "queryParameters": {
                    "earliest": "-24h@h",
                    "latest": "now"
                }
            },
            "type": "ds.search"
        },
        "ds_wIDUVhim_ds_recordtype_sources": {
            "name": "dnsguardai_dashboards_recordtype_sources2",
            "options": {
                "query": "| inputlookup anomalous_dns_lookup\n| where anomalous_type == \"TXT Record Anomalies\" OR anomalous_type == \"HINFO Record Anomalies\" OR anomalous_type == \"AXFR Record Anomalies\" OR anomalous_type == \"ANY Record Anomalies\"\n| stats count by anomalous_type",
                "queryParameters": {
                    "earliest": "$global_time.earliest$",
                    "latest": "$global_time.latest$"
                }
            },
            "type": "ds.search"
        },
        "ds_zLP3IxWQ_ds_B6kCbKQ5_ds_domainshadowing_summary": {
            "name": "dnsguardai_dashboards_recordtype_affected_source_ip",
            "options": {
                "query": "| `dns_data` | `extract_sub_domain`\n| lookup anomalous_dns_lookup domain OUTPUT anomalous_type\n| where anomalous_type == \"TXT Record Anomalies\" OR anomalous_type == \"HINFO Record Anomalies\" OR anomalous_type == \"AXFR Record Anomalies\" OR anomalous_type == \"ANY Record Anomalies\"\n| dedup src \n| stats count",
                "queryParameters": {
                    "earliest": "$global_time.earliest$",
                    "latest": "$global_time.latest$"
                }
            },
            "type": "ds.search"
        },
        "ds_zbiDyOft_ds_8FSljBFu_ds_wHrBTzr7": {
            "name": "dnsguardai_dashboards_clustering_cluster1_distinct_subdns",
            "options": {
                "query": "| summary dns_behavior_clusters\n| where cluster==1\n| table avg_distinct_subdomains",
                "queryParameters": {
                    "earliest": "-24h@h",
                    "latest": "now"
                }
            },
            "type": "ds.search"
        }
